using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
using System.Threading;
using Microsoft.Win32;
namespace FramePilot {
 public sealed class FoundGame {public string Name,Source,Launch,Folder,AppId,InstallState,SteamRoot,LastUpdated;public override string ToString(){return Name+"  |  "+Source;}}
 public sealed class GameScan {public List<FoundGame> Games=new List<FoundGame>();public List<string> Warnings=new List<string>();}
 public static class GameDiscovery {
  public static string Vdf(string text,string key){var m=Regex.Match(text,"\""+Regex.Escape(key)+"\"\\s*\"([^\"]*)\"",RegexOptions.IgnoreCase);return m.Success?m.Groups[1].Value.Replace("\\\\","\\"):null;}
  public static FoundGame SteamManifest(string path){if(new FileInfo(path).Length>1024*1024)throw new Exception("Oversized Steam manifest");string text=File.ReadAllText(path),id=Vdf(text,"appid"),name=Vdf(text,"name"),dir=Vdf(text,"installdir"),state=Vdf(text,"StateFlags"),updated=Vdf(text,"LastUpdated");if(id=="228980")return null;if(!Regex.IsMatch(id??"","^[0-9]{1,12}$")||string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(dir)||dir.IndexOfAny(new[]{'\\','/'})>=0||dir=="..")throw new Exception("Unsupported Steam manifest");long flags;if(!string.IsNullOrWhiteSpace(state)&&(!long.TryParse(state,out flags)||(flags&4)==0))return null;string folder=Path.Combine(Path.GetDirectoryName(path),"common",dir);if(!Directory.Exists(folder))throw new Exception("Installation folder not found; launcher record may be stale.");long unix;string updatedDate=long.TryParse(updated,out unix)&&unix>0&&unix<4102444800?new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddSeconds(unix).ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture):null;return new FoundGame{Name=name,Source="Steam",Launch="steam://rungameid/"+id,Folder=folder,AppId=id,InstallState=state,LastUpdated=updatedDate};}
  public static FoundGame EpicManifest(string path){if(new FileInfo(path).Length>1024*1024)throw new Exception("Oversized Epic manifest");var j=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(path));Func<string,string> get=k=>j.ContainsKey(k)?Convert.ToString(j[k]):"";string name=get("DisplayName"),app=get("AppName"),folder=get("InstallLocation");if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(app)||string.IsNullOrWhiteSpace(get("LaunchExecutable"))||get("bIsIncompleteInstall").Equals("True",StringComparison.OrdinalIgnoreCase))return null;if(j.ContainsKey("bIsApplication")&&!Convert.ToBoolean(j["bIsApplication"]))return null;if(!Directory.Exists(folder))throw new Exception(name+": installation folder not found; launcher record may be stale.");return new FoundGame{Name=name,Source="Epic Games",Folder=folder,Launch="com.epicgames.launcher://apps/"+Uri.EscapeDataString(app)+"?action=launch&silent=true"};}
  public static List<FoundGame> RiotManifest(string path){
   if(new FileInfo(path).Length>1024*1024)throw new Exception("Oversized Riot Client manifest");
   var root=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(path));object raw;if(root==null||!root.TryGetValue("associated_clients",out raw))return new List<FoundGame>();
   var clients=raw as Dictionary<string,object>;var result=new List<FoundGame>();if(clients==null)return result;
   foreach(var client in clients){string launcher=NormalizeRiotPath(client.Key);if(!File.Exists(launcher))continue;var games=client.Value as System.Collections.ArrayList;if(games==null)continue;
    foreach(object value in games){string executable=NormalizeRiotPath(Convert.ToString(value));if(!File.Exists(executable))continue;string file=Path.GetFileName(executable),name=null,product=null;
     if(file.Equals("VALORANT.exe",StringComparison.OrdinalIgnoreCase)){name="Valorant";product="valorant";}
     else if(file.Equals("LeagueClient.exe",StringComparison.OrdinalIgnoreCase)){name="League of Legends";product="league_of_legends";}
     if(product==null)continue;
     result.Add(new FoundGame{Name=name,Source="Riot Games",Launch="riotclient://launch-product="+product+"&launch-patchline=live",Folder=Path.GetDirectoryName(executable),AppId=product});
    }
   }
   return Distinct(result);
  }
  static string NormalizeRiotPath(string value){if(string.IsNullOrWhiteSpace(value))return null;try{string path=value.Trim().Replace('/','\\');return Path.GetFullPath(path);}catch{return null;}}
  public static List<string> SteamLibraryPaths(string vdf){var result=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(Match m in Regex.Matches(vdf,"\"(?:path)\"\\s*\"((?:\\\\.|[^\"])*)\"",RegexOptions.IgnoreCase)){string p=m.Groups[1].Value.Replace("\\\\","\\");if(!string.IsNullOrWhiteSpace(p))result.Add(p);}foreach(Match m in Regex.Matches(vdf,"\"[0-9]+\"\\s*\"((?:\\\\.|[^\"])*)\"")){string p=m.Groups[1].Value.Replace("\\\\","\\");if(!string.IsNullOrWhiteSpace(p))result.Add(p);}return result.ToList();}
  static void ScanSteam(GameScan scan,CancellationToken token){var roots=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry32,RegistryView.Registry64})foreach(string subkey in new[]{@"Software\Valve\Steam",@"Software\WOW6432Node\Valve\Steam"})try{token.ThrowIfCancellationRequested();using(var root=RegistryKey.OpenBaseKey(hive,view))using(var key=root.OpenSubKey(subkey)){if(key!=null){string p=Convert.ToString(key.GetValue("SteamPath")??key.GetValue("InstallPath"));if(Directory.Exists(p))roots.Add(Path.GetFullPath(p));}}}catch(OperationCanceledException){throw;}catch(Exception e){scan.Warnings.Add("Steam registry: "+e.Message);}foreach(string p in new[]{Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Steam"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Steam"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Steam")})if(Directory.Exists(p))roots.Add(Path.GetFullPath(p));var libraryOwners=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string root in roots.ToArray()){token.ThrowIfCancellationRequested();libraryOwners[root]=root;try{string vdf=Path.Combine(root,@"steamapps\libraryfolders.vdf");if(File.Exists(vdf)&&new FileInfo(vdf).Length<2*1024*1024)foreach(string p in SteamLibraryPaths(File.ReadAllText(vdf)))if(Directory.Exists(p)){string full=Path.GetFullPath(p);if(!libraryOwners.ContainsKey(full))libraryOwners[full]=root;}}catch(Exception e){scan.Warnings.Add("Steam libraries: "+e.Message);}}foreach(var library in libraryOwners){token.ThrowIfCancellationRequested();string dir=Path.Combine(library.Key,"steamapps");if(!Directory.Exists(dir))continue;try{foreach(string file in Directory.EnumerateFiles(dir,"appmanifest_*.acf").Take(2000)){token.ThrowIfCancellationRequested();try{var item=SteamManifest(file);if(item!=null){item.SteamRoot=library.Value;scan.Games.Add(item);}}catch(OperationCanceledException){throw;}catch(Exception e){scan.Warnings.Add(Path.GetFileName(file)+": "+e.Message);}}}catch(OperationCanceledException){throw;}catch(Exception e){scan.Warnings.Add("Steam scan: "+e.Message);}}}
  public static GameScan Scan(){return Scan(CancellationToken.None);}
  public static GameScan Scan(CancellationToken token){var scan=new GameScan();ScanSteam(scan,token);
   string epic=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),@"Epic\EpicGamesLauncher\Data\Manifests");if(Directory.Exists(epic))try{foreach(string file in Directory.EnumerateFiles(epic,"*.item").Take(2000))try{var item=EpicManifest(file);if(item!=null)scan.Games.Add(item);}catch(Exception e){scan.Warnings.Add(Path.GetFileName(file)+": "+e.Message);}}catch(Exception e){scan.Warnings.Add("Epic scan: "+e.Message);}
   string riot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),@"Riot Games\RiotClientInstalls.json");if(File.Exists(riot))try{scan.Games.AddRange(RiotManifest(riot));}catch(Exception e){scan.Warnings.Add("Riot scan: "+e.Message);}
   foreach(var view in new[]{RegistryView.Registry32,RegistryView.Registry64})try{using(var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,view))using(var parent=root.OpenSubKey(@"Software\GOG.com\Games")){if(parent!=null)foreach(string id in parent.GetSubKeyNames())using(var k=parent.OpenSubKey(id)){string exe=Convert.ToString(k.GetValue("exe")),folder=Convert.ToString(k.GetValue("path")),name=Convert.ToString(k.GetValue("gameName"));if(File.Exists(exe)&&Path.GetExtension(exe).Equals(".exe",StringComparison.OrdinalIgnoreCase))scan.Games.Add(new FoundGame{Name=string.IsNullOrWhiteSpace(name)?id:name,Source="GOG",Folder=folder,Launch=exe});}}}catch(Exception e){scan.Warnings.Add("GOG scan: "+e.Message);}scan.Games=Distinct(scan.Games);return scan;
  }
  public static List<FoundGame> Distinct(IEnumerable<FoundGame> items){return items.GroupBy(x=>x.Source=="Steam"&&!string.IsNullOrWhiteSpace(x.AppId)?"Steam:"+x.AppId:x.Launch,StringComparer.OrdinalIgnoreCase).Select(x=>x.First()).OrderBy(x=>x.Name).ToList();}
  public static GameScan Folder(string root){var scan=new GameScan();var queue=new Queue<string>();queue.Enqueue(Path.GetFullPath(root));int visited=0;while(queue.Count>0&&visited++<5000&&scan.Games.Count<1000){string dir=queue.Dequeue();try{if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;foreach(string file in Directory.EnumerateFiles(dir,"*.exe").Take(1000)){string name=Path.GetFileNameWithoutExtension(file);if(Regex.IsMatch(name,"unins|uninstall|setup|redist|crash|anticheat|vcredist|dxsetup",RegexOptions.IgnoreCase))continue;scan.Games.Add(new FoundGame{Name=name,Source="EXE candidate (verify)",Launch=file,Folder=dir});}foreach(var child in Directory.EnumerateDirectories(dir).Take(2000)){if(queue.Count>=10000){scan.Warnings.Add("Folder queue limit reached; choose a smaller games folder.");break;}queue.Enqueue(child);}}catch(Exception e){scan.Warnings.Add(dir+": "+e.Message);}}if(queue.Count>0)scan.Warnings.Add("Scan limit reached. Choose a smaller folder for remaining games.");return scan;}
  public static bool CanLaunch(FoundGame item){if(item==null||string.IsNullOrWhiteSpace(item.Launch))return false;if(item.Source=="Steam")return Regex.IsMatch(item.Launch,"^steam://rungameid/[0-9]{1,12}$");if(item.Source=="Epic Games")return Regex.IsMatch(item.Launch,"^com\\.epicgames\\.launcher://apps/[A-Za-z0-9%_.~-]+\\?action=launch&silent=true$");if(item.Source=="Riot Games")return Regex.IsMatch(item.Launch,"^riotclient://launch-product=(valorant|league_of_legends)&launch-patchline=live$",RegexOptions.IgnoreCase);return Path.IsPathRooted(item.Launch)&&File.Exists(item.Launch)&&new[]{".exe",".lnk"}.Contains(Path.GetExtension(item.Launch),StringComparer.OrdinalIgnoreCase);}
 }
 public sealed class DriverOffer {public string Title,Model,Provider;}
 public sealed class DriverOffers {public string Error;public List<DriverOffer> Updates=new List<DriverOffer>();public static DriverOffers Search(){var result=new DriverOffers();try{dynamic session=Activator.CreateInstance(Type.GetTypeFromProgID("Microsoft.Update.Session",true));session.ClientApplicationID="FramePilot driver availability";dynamic searcher=session.CreateUpdateSearcher();searcher.Online=true;dynamic found=searcher.Search("IsInstalled=0 and IsHidden=0 and Type='Driver'");if((int)found.ResultCode!=2)throw new Exception("Windows returned an incomplete search ("+(int)found.ResultCode+").");for(int i=0;i<(int)found.Updates.Count;i++){dynamic update=found.Updates.Item(i);result.Updates.Add(new DriverOffer{Title=(string)update.Title,Model=(string)update.DriverModel,Provider=(string)update.DriverProvider});}}catch(Exception e){result.Error=e.Message;}return result;}
  public static int Worker(string file){var result=Search();File.WriteAllText(file,new JavaScriptSerializer().Serialize(result));return result.Error==null?0:1;}
 }
}


